using namespace std;
int longestPalPrefix(const string& t){
    string u = t + '#' + string(t.rbegin(), t.rend());
    vector<int> pi(u.size(), 0);
    for(size_t i=1;i<u.size();i++){
        int j=pi[i-1];
        while(j && u[i]!=u[j]) j=pi[j-1];
        if(u[i]==u[j]) j++;
        pi[i]=j;
    }
    return pi.back();
}
int main(){
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int T; cin>>T;
    while(T--){
        string s; cin>>s;
        int n=s.size(), k=0;
        while(k < n-1-k && s[k]==s[n-1-k]) k++;
        string mid = s.substr(k, n-2*k);
        string rmid(mid.rbegin(), mid.rend());
        int lp = longestPalPrefix(mid), ls = longestPalPrefix(rmid);
        string best = (lp>=ls) ? mid.substr(0,lp) : mid.substr(mid.size()-ls);
        cout<<s.substr(0,k)<<best<<s.substr(n-k)<<"\n";
    }
}

