int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,m; scanf("%d %d",&n,&m);
        vector<vector<pair<int,int>>> g(n);
        for(int i=0;i<m;i++){ int u,v,w; scanf("%d %d %d",&u,&v,&w); u--; v--; g[u].push_back({v,w}); g[v].push_back({u,w}); }
        vector<ll> s(n); for(auto& x:s){ int y; scanf("%d",&y); x=y; }
        // state (v,c): standing at v, currently riding the bike bought in city c
        vector<ll> d((size_t)n*n, LLONG_MAX);
        priority_queue<tuple<ll,int,int>, vector<tuple<ll,int,int>>, greater<>> pq;
        d[0]=0; pq.push({0,0,0});
        while(!pq.empty()){
            auto [dd,v,c]=pq.top(); pq.pop();
            if(dd!=d[(size_t)v*n+c]) continue;
            if(s[v]<s[c]){ size_t id=(size_t)v*n+v; if(dd<d[id]){ d[id]=dd; pq.push({dd,v,v}); } }
            for(auto [u,w]:g[v]){
                ll nd=dd+(ll)w*s[c]; size_t id=(size_t)u*n+c;
                if(nd<d[id]){ d[id]=nd; pq.push({nd,u,c}); }
            }
        }
        ll ans=LLONG_MAX;
        for(int c=0;c<n;c++) ans=min(ans, d[(size_t)(n-1)*n+c]);
        printf("%lld\n", ans);
    }
}

