    int t; scanf("%d",&t);
    static char buf[200005];
    while(t--){
        scanf("%s",buf);
        string s(buf); int n=s.size();
        int opens=0; for(char c:s) if(c=='(') opens++;
        int K = n/2 - opens;                       // '?' that must become '('
        // T: the first K question marks become '(', the rest ')'
        string T=s; int used=0;
        for(int i=0;i<n;i++) if(s[i]=='?'){ T[i] = (used<K) ? '(' : ')'; used++; }
        vector<int> bal(n);
        int b=0; for(int i=0;i<n;i++){ b += (T[i]=='(') ? 1 : -1; bal[i]=b; }
        // fb[k]: first index >= k where bal < 2
        vector<int> fb(n+1, n);
        for(int k=n-1;k>=0;k--) fb[k] = (bal[k]<2) ? k : fb[k+1];
        // nq[k]: first index >= k that is an original '?' turned into ')'
        const int INF=INT_MAX;
        vector<int> nq(n+2, INF);
        for(int k=n-1;k>=0;k--) nq[k] = (s[k]=='?' && T[k]==')') ? k : nq[k+1];
        bool unique=true;
        for(int i=0;i<n && unique;i++){
            if(s[i]=='?' && T[i]=='('){
                int j = nq[i+1];
                if(j!=INF && j<=fb[i]) unique=false;
            }
        }
        puts(unique ? "YES" : "NO");
    }
}

