using namespace std;
typedef long long ll;
// element value = b^(2^t) (b = original value >= 2); geq: b^(2^t) >= pb^(2^pk)
bool geq(ll b, ll t, ll pb, ll pk){
    if(t>=pk){ ll v=b; for(ll j=0; j<t-pk && v<=1000000; j++) v=v*v; return v>=pb; }
    ll w=pb; for(ll j=0; j<pk-t && w<=1000000; j++) w=w*w;
    return w<=1000000 && w<=b;
}
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n; scanf("%d",&n);
        vector<ll> a(n); for(auto& x:a) scanf("%lld",&x);
        ll ops=0, pb=a[0], pk=0; bool ok=true;
        for(int i=1;i<n && ok;i++){
            ll b=a[i];
            if(pb<=1){ if(b<pb) ok=false; else { pb=b; pk=0; } continue; }
            if(b<=1){ ok=false; break; }
            ll t=max(0LL, pk+(ll)floor(log2((double)pb)/log2((double)b))-3);
            while(t>0 && geq(b,t-1,pb,pk)) t--;
            while(!geq(b,t,pb,pk)) t++;
            ops+=t; pb=b; pk=t;
        }
        printf("%lld\n", ok ? ops : -1LL);
    }
}

