        for(int i=1;i<=n;i++) scanf("%lld",&p[i]);
        for(int i=1;i<=n;i++) scanf("%lld",&h[i]);
        vector<vector<int>> g(n+1);
        for(int i=0;i<n-1;i++){ int a,b; scanf("%d %d",&a,&b); g[a].push_back(b); g[b].push_back(a); }
        // BFS order from root 1, then process in reverse
        vector<int> order, par(n+1,0); order.reserve(n);
        order.push_back(1); par[1]=-1;
        for(size_t i=0;i<order.size();i++){ int v=order[i]; for(int u:g[v]) if(u!=par[v]){ par[u]=v; order.push_back(u);} }
        vector<ll> s(n+1,0), good(n+1,0), childGood(n+1,0);
        bool ok=true;
        for(int i=n-1;i>=0;i--){
            int v=order[i];
            s[v]+=p[v];
            if(par[v]>0) s[par[v]]+=s[v];
        }
        for(int i=n-1;i>=0 && ok;i--){
            int v=order[i];
            ll x=h[v]+s[v];
            if(x<0 || x%2!=0){ ok=false; break; }
            good[v]=x/2;
            if(good[v]>s[v] || good[v]<childGood[v]){ ok=false; break; }
            if(par[v]>0) childGood[par[v]]+=good[v];
        }
        puts(ok?"YES":"NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// L = number of free cells between two consecutive trees
ll Ssum(ll L){ ll h=L/2; return L%2==0 ? h*(h+1) : (h+1)*(h+1); }
int main(){
    int n; ll m; scanf("%d %lld",&n,&m);
    vector<ll> x(n); for(auto& v:x) scanf("%lld",&v);
    sort(x.begin(), x.end());
    auto cnt=[&](ll D){ ll c=2*D; for(int i=0;i+1<n;i++){ ll L=x[i+1]-x[i]-1; c+=min(L,2*D);} return c; };
    ll lo=1, hi=m;
    while(lo<hi){ ll mid=(lo+hi)/2; if(cnt(mid)>=m) hi=mid; else lo=mid+1; }
    ll D=lo, E=D-1;
    ll cE=0, sumE=0;
    if(E>0){
        cE=2*E; sumE=E*(E+1);
        for(int i=0;i+1<n;i++){
            ll L=x[i+1]-x[i]-1; if(L<=0) continue;
            cE+=min(L,2*E);
            sumE += (2*E<=L) ? E*(E+1) : Ssum(L);
        }
    }
    ll ans = sumE + (m-cE)*D;
    vector<pair<ll,ll>> cand;  // (distance, position)
    for(ll k=1;k<=D;k++){ cand.push_back({k, x[0]-k}); cand.push_back({k, x[n-1]+k}); }
    for(int i=0;i+1<n;i++){
        ll a=x[i], b=x[i+1], L=b-a-1; if(L<=0) continue;
        ll kk=min(D,L);
        for(ll k=1;k<=kk;k++) cand.push_back({min(k,L+1-k), a+k});
        for(ll k=1;k<=kk;k++){ ll pos=b-k; if(pos>a+kk) cand.push_back({min(k,L+1-k), pos}); }
    }
    sort(cand.begin(), cand.end());
    printf("%lld\n", ans);
    for(ll j=0;j<m;j++) printf("%lld ", cand[j].second);
    printf("\n");
}

