int main(){
    int t; scanf("%d",&t);
    while(t--){
        ll n,m; scanf("%lld %lld",&n,&m);
        ll k=1; while(k<=m) k<<=1;          // smallest power of two > m
        ll ans;
        if(n>=k) ans=0;                     // n^0 = n > m, so 0 is missing
        else if(m+1>k-1) ans=k;             // no y in (m,k): answer is k
        else {
            ll best=LLONG_MAX, L=m+1, R=k-1;  // y = n^x must lie in (m,k)
            while(L<=R){
                int j=0;
                while(true){
                    ll sz=1LL<<(j+1);
                    if(L%sz==0 && L+sz-1<=R) j++; else break;
                }
                best=min(best, ((n>>j)^(L>>j))<<j);
                L += 1LL<<j;
            }
            ans=best;
        }
        printf("%lld\n", ans);
    }
}

