#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<vector<int>> g(n+1);
    vector<int> deg(n+1,0);
    for(int i=0;i<n-1;i++){ int a,b; scanf("%d %d",&a,&b); g[a].push_back(b); g[b].push_back(a); deg[a]++; deg[b]++; }
    // depth parity from root 1
    vector<int> par(n+1,-1); queue<int> q; q.push(1); par[1]=0;
    while(!q.empty()){ int v=q.front(); q.pop(); for(int u:g[v]) if(par[u]<0){ par[u]=par[v]^1; q.push(u);} }
    int leafPar=-1; bool same=true;
    for(int v=1;v<=n;v++) if(deg[v]==1){ if(leafPar<0) leafPar=par[v]; else if(par[v]!=leafPar) same=false; }
    int mn = same ? 1 : 3;
    long long mx = n-1;
    for(int v=1;v<=n;v++){
        if(deg[v]==1) continue;
        int c=0; for(int u:g[v]) if(deg[u]==1) c++;
        if(c>1) mx -= (c-1);
    }
    printf("%d %lld\n", mn, mx);
}

