#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// count subarrays with sum s whose elements all satisfy pred, using prefix-sum hash counting
ll countSeg(const vector<ll>& a, ll s, ll x, bool strict){
    // elements allowed: a_i <= x (or a_i < x when strict)
    ll res=0; int n=a.size();
    unordered_map<ll,int> seen; seen.reserve(2*n+4);
    ll pre=0; seen[0]=1; int cnt=0;
    // process maximal runs of allowed elements
    int i=0;
    while(i<n){
        bool ok = strict ? a[i]<x : a[i]<=x;
        if(!ok){ i++; continue; }
        int j=i; seen.clear(); pre=0; seen[0]=1;
        while(j<n){
            bool okj = strict ? a[j]<x : a[j]<=x;
            if(!okj) break;
            pre += a[j];
            auto it=seen.find(pre-s);
            if(it!=seen.end()) res += it->second;
            seen[pre]++;
            j++;
        }
        i=j;
    }
    (void)cnt;
    return res;
}
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll s, x; scanf("%d %lld %lld",&n,&s,&x);
        vector<ll> a(n); for(auto& v:a) scanf("%lld",&v);
        // subarrays with max exactly x = (all elements <= x) minus (all elements < x)
        printf("%lld\n", countSeg(a,s,x,false) - countSeg(a,s,x,true));
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// Alice moves a[0..2] = rock, scissors, paper; Bob b[0..2] likewise.
// Alice beats Bob's j when j == (i+1)%3.
ll maxflow(const ll a[3], const ll b[3], bool win){
    ll best=LLONG_MAX;
    for(int S=0;S<8;S++){                 // S: subset of Alice's types on the source side
        ll cut=0;
        bool nb[3]={false,false,false};
        for(int i=0;i<3;i++){
            if(S>>i&1){
                for(int j=0;j<3;j++){
                    bool edge = win ? (j==(i+1)%3) : (j!=(i+1)%3);
                    if(edge) nb[j]=true;
                }
            } else cut += a[i];
        }
        for(int j=0;j<3;j++) if(nb[j]) cut += b[j];
        best=min(best,cut);
    }
    return best;
}
int main(){
    ll n; scanf("%lld",&n);
    ll a[3], b[3];
    scanf("%lld %lld %lld",&a[0],&a[1],&a[2]);
    scanf("%lld %lld %lld",&b[0],&b[1],&b[2]);
    ll mxWins = maxflow(a,b,true);
    ll mnWins = n - maxflow(a,b,false);
    printf("%lld %lld\n", mnWins, mxWins);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,q; scanf("%d %d",&n,&q);
        vector<ll> a(n); for(auto& x:a) scanf("%lld",&x);
        vector<ll> P(n+1,0), X(n+1,0);
        for(int i=0;i<n;i++){ P[i+1]=P[i]+a[i]; X[i+1]=X[i]^a[i]; }
        // f(l,r)=sum-xor is non-decreasing when extending, so the maximum is f(1,n)
        auto f=[&](int l,int r)->ll{ return (P[r]-P[l-1]) - (X[r]^X[l-1]); };
        ll F=f(1,n);
        int l=1; ll bestLen=LLONG_MAX; int bl=1, br=1;
        for(int r=1;r<=n;r++){
            while(l+1<=r && f(l+1,r)>=F) l++;
            if(f(l,r)==F && r-l+1<bestLen){ bestLen=r-l+1; bl=l; br=r; }
        }
        // q is always 1 in the easy version, with L=1, R=n
        for(int i=0;i<q;i++){ int L,R; scanf("%d %d",&L,&R); printf("%d %d\n", bl, br); }
    }
}

