    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n; scanf("%d",&n);
    vector<vector<pair<int,ll>>> g(n+1);
    ll S=0;
    for(int i=0;i<n-1;i++){ int a,b; ll w; scanf("%d %d %lld",&a,&b,&w); g[a].push_back({b,w}); g[b].push_back({a,w}); S+=w; }
    // farthest distance from city 1
    vector<ll> d(n+1,-1); d[1]=0; vector<int> st={1}; ll far=0;
    while(!st.empty()){ int v=st.back(); st.pop_back(); far=max(far,d[v]); for(auto [u,w]:g[v]) if(d[u]<0){ d[u]=d[v]+w; st.push_back(u);} }
    // must walk every edge twice, except the final one-way path to the farthest city
    printf("%lld\n", 2*S-far);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<int> a(n), b(n);
        for(auto& x:a) scanf("%d",&x);
        for(auto& x:b) scanf("%d",&x);
        const int FULL=(1<<30)-1;
        int ans=0;
        for(int bit=29;bit>=0;bit--){
            int cand = ans | (1<<bit);
            // a_i ^ b_j has all bits of cand iff (a_i & cand) == (~b_j & cand)
            vector<int> x(n), y(n);
            for(int i=0;i<n;i++){ x[i]=a[i]&cand; y[i]=(~b[i]&FULL)&cand; }
            sort(x.begin(),x.end()); sort(y.begin(),y.end());
            if(x==y) ans=cand;
        }
        printf("%d\n", ans);
    }
}
